package abstraction_interfaces.assigment_problems;

import java.util.*;public class CityCabFareMeter {interface NightService{double night(double fare);}abstract static class Cab{double km;Cab(double k){km=k;}abstract double rate();double fare(){return Math.max(100,km*rate());}}static class Mini extends Cab{Mini(double k){super(k);}double rate(){return 10;}}static class Sedan extends Cab implements NightService{Sedan(double k){super(k);}double rate(){return 14;}public double night(double f){return f*1.2;}}static class SUV extends Cab implements NightService{SUV(double k){super(k);}double rate(){return 18;}public double night(double f){return f*1.2;}}public static void main(String[] z){Scanner s=new Scanner(System.in);int n=s.nextInt();double total=0;for(int i=0;i<n;i++){String t=s.next();double km=s.nextDouble();String time=s.next();Cab c=t.equals("MINI")?new Mini(km):t.equals("SEDAN")?new Sedan(km):new SUV(km);if(time.equals("NIGHT")&&!(c instanceof NightService)){System.out.println(t+": night service not available");continue;}double f=c.fare();if(time.equals("NIGHT"))f=((NightService)c).night(f);System.out.printf(Locale.US,"%s: %.2f%n",t,f);total+=f;}System.out.printf(Locale.US,"Total: %.2f%n",total);}}
